# This script configure winget if the pc does not see it yet.Write-Host "[⚙️] Configuring Windows package manager"Write-Host "Please wait a few second"$windowsApp = Join-Path $Home "Appdata/Local/Microsoft/WindowsApps"function addManagerToPath{    Write-Host "Package manager found"    $exist = $env:PATH.split(";") |       ForEach-Object {$_.trimEnd("/")} |      Where-Object {$_ -ieq $windowsApp}    if ($exist) {        Write-Host "[🙂‍↔️] Package manager already configured!"    }    else {        Write-Host "[🤕] Package manager is not in path"        Write-Host "Adding package manager to path..."        $path = [Environment]::GetEnvironmentVariable("Path", "User")        [Environment]::SetEnvironmentVariable("Path", "$path;$windowsApp", "User")        Write-Host "[😄] Windows package manager is now in the Path!"    }}winget --versionif ($LASTEXITCODE -eq 0) {    Write-Host "[✅] Windows package manager already installed!"}else{     if (Test-Path (Join-Path $windowsApp "winget.exe") -PathType Leaf) {        addManagerToPath    }    else {        Write-Host "There is no package manager!"        Write-Host "[⚙️] Installing Windows package manager..."        $bundle = "$env:TEMP\Microsoft.DesktopAppInstaller.msixbundle"        Invoke-WebRequest `            -Uri "https://aka.ms/getwinget" `            -OutFile $bundle        Add-AppxPackage $bundle        & (Join-Path $windowsApp "winget.exe") --version        if ($LASTEXITCODE -eq 0) {            Write-Host "[✅] Windows package manager successfuly installed!"        }        else {            if (Test-Path (Join-Path $windowsApp "winget.exe") -PathType Leaf) {                addManagerToPath            }            else {                Write-Host "[❌] Failed to install winget."            }        }    }}